// 1. Texto retornado pelo AI Agent
let raw = $json.output;

// 2. Remove ```json e ```
raw = raw.replace(/```json|```/g, '').trim();

// 3. Parse do JSON da IA
let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  throw new Error('JSON inválido retornado pela IA');
}

// 4. ID da task vindo DIRETO do Asana (fonte confiável)
const asanaTaskId = $node["Asana | Get New Task Details1"].json.gid || "";

// 5. Retorno final para a planilha
return [
  {
    json: {
      asana_task_id: asanaTaskId,

      nome_projeto: data.nome_projeto || "",
      coluna: data.coluna || "",
      titulo_evento: data.titulo_evento || "",
      horas_consultoria: data.horas_consultoria || "",
      numero_ll: data.numero_ll || "",
      numero_contrato: data.numero_contrato || "",
      nome_consultor: data.nome_consultor || "",
      valor_pago_consultor: data.valor_pago_consultor || "",
      parcelas_pagas: data.parcelas_pagas || "",
      parcelas_consultor: data.parcelas_consultor || "",
      nome_cliente_atendido: data.nome_cliente_atendido || "",
      cnpj_cliente: data.cnpj_cliente || "",
      data_inicio: data.data_inicio || "",
      data_termino: data.data_termino || "",
      valor_pago_cliente: data.valor_pago_cliente || ""
    }
  }
];

return items.map(item => ({
  json: {
    baseSubtaskGid: item.json.gid,      // da subtarefa base
    baseSubtaskName: item.json.name,
    newSubtaskGid: item.json.new_gid    // da subtarefa criada
  }
}));

return items.map(item => {
  const stories = Array.isArray(item.json.data) ? item.json.data : [];

  // Verifica se existe pelo menos um comentário válido
  const hasComment = stories.some(story =>
    story.resource_subtype === 'comment_added' &&
    typeof story.text === 'string' &&
    story.text.trim() !== ''
  );

  // Descrição original da subtarefa
  const notesOriginal =
    item.json.notes && typeof item.json.notes === 'string'
      ? item.json.notes.trim()
      : '';

  // Monta descrição final
  let descricaoFinal = '';

  if (hasComment) {
    descricaoFinal = '#wpp';
    if (notesOriginal !== '') {
      descricaoFinal += '\n\n' + notesOriginal;
    }
  } else {
    descricaoFinal = notesOriginal;
  }

  return {
    json: {
      ...item.json,
      hasComment,
      descricao_subtarefa: descricaoFinal
    }
  };
});

