// Projeto
const nomeProjeto =
  $('Edit Fields6').item.json.Nome_Projeto ?? 'Projeto não identificado';

// Card (tarefa pai)
const nomeCard =
  $('Get a task1').item.json.name ?? 'Card não identificado';

// Subtarefa
const nomeSubtarefa =
  $('Edit Fields5').item.json.subtarefa
  ?? $('Edit Fields8').item.json.tarefa_concluida
  ?? 'Subtarefa não identificada';

// Link da subtarefa
const linkSubtarefa =
  $('Edit Fields5').item.json.Link_Subtarefa ?? '';

// Usuário que concluiu
const usuarioConclusao =
  $('Edit Fields8').item.json.Usuario_Acao ?? 'Usuário não identificado';

// Data da conclusão
const dataConclusao =
  $('Edit Fields8').item.json.data_conclusão ?? null;

const dataFormatada = dataConclusao
  ? new Date(dataConclusao).toLocaleString('pt-BR')
  : 'Data não identificada';

// ===============================
// Mensagem final
// ===============================
const mensagem = `✅ Subtarefa concluída!

📌 Projeto: ${nomeProjeto}
🗂 Card: ${nomeCard}
📝 Subtarefa: ${nomeSubtarefa}

👤 Concluído por: ${usuarioConclusao}
🕒 Data: ${dataFormatada}

🔗 ${linkSubtarefa}`;

// ===============================
// Retorno
// ===============================
return [
  {
    json: {
      mensagem
    }
  }
];

// ===============================
// Identificar quem concluiu a tarefa (Asana)
// ===============================

// Puxa diretamente o output do HTTP Request de stories
const stories = $items("HTTP Request1")[0]?.json?.data ?? [];

// Segurança
if (!Array.isArray(stories)) {
  return [{
    json: {
      usuario_conclusao: 'Estrutura inválida',
      usuario_gid: null,
      data_conclusao: null
    }
  }];
}

// Filtra apenas conclusões
const conclusoes = stories.filter(story =>
  story.resource_subtype === 'marked_complete'
);

// Se não encontrou conclusão
if (conclusoes.length === 0) {
  return [{
    json: {
      usuario_conclusao: 'Não identificado',
      usuario_gid: null,
      data_conclusao: null
    }
  }];
}

// Pega a última conclusão (mais recente)
const ultimaConclusao = conclusoes.sort(
  (a, b) => new Date(a.created_at) - new Date(b.created_at)
).pop();

return [{
  json: {
    usuario_conclusao: ultimaConclusao.created_by?.name ?? 'Desconhecido',
    usuario_gid: ultimaConclusao.created_by?.gid ?? null,
    data_conclusao: ultimaConclusao.created_at ?? null
  }
}];
